    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 limit, uint256 wrongAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wrongAmount)); require(wrongAmount <= 1000000000000000000000000000000);
        require(wrongAmount != limit);
        require(address(this).balance >= limit);
        c.AdjustBetAmounts(limit); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.wager{value: wrongAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && !c.hasPlayerWagered(address(this)) && c.currentBetLimit() == limit);
    }
    receive() external payable {}
