pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 limit, uint256 wrongAmount) internal {
        wrongAmount = bound(wrongAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(wrongAmount != limit);
        vm.assume(address(this).balance >= limit);
        try c.AdjustBetAmounts(limit) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        bool reverted;
        try c.wager{value: wrongAmount}() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && !c.hasPlayerWagered(address(this)) && c.currentBetLimit() == limit);
    }

    function testFuzz_run(uint256 limit, uint256 wrongAmount) public {
        _run(limit, wrongAmount);
    }

    receive() external payable {}
}
